from author import page, section as s
import sys

def write(id,locale,title,description,lead,sections,related):
    page(id,locale,'company',title,description,'ARTIFACTORY / '+('COMPANY' if locale=='en' else 'FIRMA'),lead,sections,related)

def investors():
    write('investors','en','Explore Artifactory as a company.','A company-level investment discussion connecting ArtiSense sensing research, AIFIELD photonic engineering tools, available evidence and open development questions.','Two related technical directions. A company proposition to examine through the work, its limits and the next evidence it needs.',[
        s('thesis','Sensing technology and the tools to design it.','Artifactory brings together ArtiSense and AIFIELD in a proposed positioning around sensing and photonic engineering. The investment subject is Artifactory as a company. Understanding that proposition means assessing the role and maturity of each project, rather than treating them as interchangeable products.','The internal sensing-design example provides a concrete connection: a measurement objective creates a photonic design question, and engineering tools help investigate a candidate structure. This connection is a technical rationale to explore, not evidence of shared IP ownership or commercial success.'),
        s('projects','Two evidence paths, at different boundaries.','ArtiSense is a proposed miniaturized chemical-sensing system. The supplied glucose-related work concerns optical feasibility and chip design; physical measurement accuracy and intended wearable use remain unvalidated.','AIFIELD’s September 2026 summary describes classical design and simulation work, partial agent assistance and separate neural field research. Its internal example supports an engineering discussion, while current access, commercial readiness and the research limitations need their own assessment.',links=['artisense','aifield']),
        s('questions','What a useful investment discussion should establish.','A company assessment needs current evidence beyond this technical overview. The materials supplied for the site do not establish a current funding round, instrument, valuation, revenue, market validation or committed pilot. A historical project funding proposal is not presented as a current company ask.','The next conversation can identify which evidence may be shared and who can answer questions about company structure, ownership, development resources and commercial assumptions. No confidential investor pack or numerical market case is implied by this page.',items=['Which technical risks most affect the company proposition?','What would a reproducible design or physical result establish?','Which commercial assumptions need customer evidence?'],links=['about']),
        s('milestones','Potential milestones should reduce a stated uncertainty.','Possible development steps include an inspectable design-and-simulation record for AIFIELD and a controlled optical comparison for ArtiSense. Neural field work would need a clearly bounded evaluation that includes unsuccessful cases and full workflow cost.','These are proposed evidence needs, not funded commitments, promised dates or completed results. Start an investment enquiry to discuss the company, the evidence currently available and a suitable next conversation.',links=['contact'])],['artisense','aifield','about','contact'])
    write('investors','pl','Poznaj Artifactory jako firmę.','Rozmowa inwestycyjna na poziomie firmy: badania ArtiSense, narzędzia fotoniczne AIFIELD, dostępne dowody i otwarte pytania rozwojowe.','Dwa powiązane kierunki techniczne. Propozycja firmy do oceny przez pryzmat prac, ich ograniczeń i kolejnych potrzebnych dowodów.',[
        s('thesis','Technologia pomiarowa i narzędzia do jej projektowania.','Artifactory łączy ArtiSense i AIFIELD w proponowanym pozycjonowaniu wokół pomiarów i inżynierii fotonicznej. Przedmiotem rozmowy inwestycyjnej jest Artifactory jako firma. Ocena tej propozycji wymaga zrozumienia roli i dojrzałości każdego projektu.','Wewnętrzny przykład projektowy pokazuje konkretne powiązanie: cel pomiarowy tworzy pytanie projektowe, a narzędzia inżynierskie pomagają zbadać proponowaną strukturę. To uzasadnienie techniczne do analizy, a nie dowód wspólnej własności intelektualnej lub sukcesu komercyjnego.'),
        s('projects','Dwie ścieżki dowodów, różne granice.','ArtiSense to proponowany zminiaturyzowany system pomiaru składu chemicznego. Dostarczone prace związane z glukozą dotyczą wykonalności optycznej i projektu chipu; dokładność pomiaru fizycznego oraz zamierzone użycie ubieralne pozostają niezwalidowane.','Podsumowanie AIFIELD z września 2026 opisuje klasyczne projektowanie i symulację, częściowe wsparcie agentowe oraz odrębne badania neuronowych modeli pola. Wewnętrzny przykład uzasadnia rozmowę inżynierską, a bieżący dostęp, gotowość komercyjna i ograniczenia badań wymagają osobnej oceny.',links=['artisense','aifield']),
        s('questions','Co powinna wyjaśnić rozmowa inwestycyjna.','Ocena firmy wymaga aktualnych dowodów wykraczających poza ten opis techniczny. Materiały strony nie potwierdzają bieżącej rundy finansowania, instrumentu, wyceny, przychodów, walidacji rynku ani uzgodnionego pilotażu. Historyczna propozycja finansowania projektu nie jest przedstawiana jako obecna oferta firmy.','Kolejna rozmowa może określić dostępne materiały i osoby odpowiedzialne za pytania o strukturę firmy, własność, zasoby rozwojowe oraz założenia komercyjne. Strona nie sugeruje istnienia poufnego pakietu inwestorskiego ani liczbowej analizy rynku.',items=['Które ryzyka techniczne najbardziej wpływają na propozycję firmy?','Co wykazałby odtwarzalny wynik projektowy lub fizyczny?','Które założenia komercyjne wymagają dowodów od klientów?'],links=['about']),
        s('milestones','Potencjalny etap powinien zmniejszać określoną niepewność.','Możliwe kolejne kroki to możliwy do oceny zapis projektu i symulacji AIFIELD oraz kontrolowane porównanie optyczne ArtiSense. Badania neuronowego pola wymagałyby oceny o jasnych granicach, obejmującej nieudane przypadki i koszt całego procesu.','To proponowane potrzeby dowodowe, a nie sfinansowane zobowiązania, obiecane daty czy zakończone wyniki. Zapytanie inwestycyjne pozwala rozpocząć rozmowę o firmie, dostępnych dowodach i odpowiednim następnym kroku.',links=['contact'])],['artisense','aifield','about','contact'])

def approach():
    write('approach','en','Let the evidence define the next question.','A proposed evidence-oriented approach to photonic development: distinguish problems, models, designs, prototypes and physical measurements.','A clear progression helps explain what has been learned, what remains an assumption and what a next experiment should resolve.',[
        s('progression','Keep the steps distinguishable.','A problem defines a desired outcome. A model expresses assumptions about how a system behaves. A design turns those assumptions into a candidate structure. A prototype is a physical realization to examine, and a measurement compares observed behavior with an appropriate reference.','Moving through these steps is not automatic. A useful result may call for a revised model or a narrower question before further development. This is a proposed way to organize the supplied work, not a claim of an independently audited company procedure.'),
        s('evidence','Name the kind of evidence.','The word “result” can hide very different levels of support. Keep the category and the limits attached when summarizing a project.',rows=[['Concept','Describes intended behavior and architecture. It identifies what needs to be established.'],['Simulation','Estimates behavior inside a defined model. Its inputs, assumptions and comparison method remain essential.'],['Measured evidence','Describes observations under stated physical conditions. Repeatability, reference and uncertainty determine its meaning.']]),
        s('example','The sensing-design example makes the distinction concrete.','An intended optical sensing response motivates a candidate photonic design. AIFIELD’s internal glucose-related example concerns that design and simulated behavior. It does not establish that a fabricated ArtiSense device measures glucose accurately.','The next useful question depends on the gap: inspect the model and comparison first, then define what a physical experiment would need to establish. Progress in design does not automatically close the measurement gap.',links=['artisense','aifield']),
        s('decisions','Use uncertainty to make a specific request.','A discussion becomes more useful when it names an unknown, a possible observation and the expertise needed to interpret it. Retain failed cases and unexpected behavior alongside favorable results.','For a potential collaboration, describe the question you could help answer and the conditions under which an answer would be meaningful. Topics can include optical measurement, fabrication constraints, model comparisons or engineering workflow evaluation.',links=['partnerships'])],['artisense','aifield','partnerships'])
    write('approach','pl','Niech dowody wyznaczają kolejne pytanie.','Proponowane podejście do rozwoju fotoniki oparte na dowodach: rozróżnienie problemu, modelu, projektu, prototypu i pomiaru fizycznego.','Jasna kolejność pomaga wyjaśnić, czego się dowiedziano, co pozostaje założeniem i co powinien rozstrzygnąć następny eksperyment.',[
        s('progression','Zachowaj rozróżnienie etapów.','Problem określa pożądany rezultat. Model wyraża założenia o zachowaniu systemu. Projekt zamienia je w proponowaną strukturę. Prototyp jest realizacją fizyczną do zbadania, a pomiar porównuje obserwowane zachowanie z odpowiednim odniesieniem.','Przejście między etapami nie jest automatyczne. Użyteczny wynik może wymagać poprawienia modelu lub zawężenia pytania przed dalszym rozwojem. To propozycja uporządkowania dostarczonych prac, a nie deklaracja niezależnie audytowanej procedury firmy.'),
        s('evidence','Nazwij rodzaj dowodu.','Słowo „wynik” może ukrywać różne poziomy uzasadnienia. Przy podsumowaniu projektu zachowaj kategorię i jej ograniczenia.',rows=[['Koncepcja','Opisuje zamierzone zachowanie i architekturę. Wskazuje, co trzeba wykazać.'],['Symulacja','Szacuje zachowanie w określonym modelu. Dane, założenia i metoda porównania pozostają niezbędne.'],['Dowód pomiarowy','Opisuje obserwacje w określonych warunkach fizycznych. Powtarzalność, odniesienie i niepewność określają jego znaczenie.']]),
        s('example','Przykład projektowania pomiaru pokazuje tę różnicę.','Zamierzona odpowiedź optyczna motywuje proponowany projekt fotoniczny. Wewnętrzny przykład AIFIELD związany z glukozą dotyczy projektu i symulowanego zachowania. Nie wykazuje, że wykonane urządzenie ArtiSense dokładnie mierzy glukozę.','Kolejne użyteczne pytanie zależy od luki: najpierw oceń model i porównanie, następnie określ wymagania eksperymentu fizycznego. Postęp projektu nie zamyka automatycznie luki pomiarowej.',links=['artisense','aifield']),
        s('decisions','Zamień niepewność w konkretne pytanie.','Rozmowa staje się użyteczniejsza, gdy nazywa niewiadomą, możliwą obserwację i wiedzę potrzebną do jej interpretacji. Zachowuj nieudane przypadki oraz nieoczekiwane zachowanie obok korzystnych wyników.','Przy potencjalnej współpracy opisz pytanie, na które możesz pomóc odpowiedzieć, oraz warunki nadające odpowiedzi znaczenie. Tematy mogą obejmować pomiary optyczne, ograniczenia wytwarzania, porównania modeli lub ocenę procesu inżynierskiego.',links=['partnerships'])],['artisense','aifield','partnerships'])

def about():
    write('about','en','Artifactory. Sensing and photonic engineering.','Meet the company-level focus connecting ArtiSense sensing research and AIFIELD design tools, with clear evidence and collaboration paths.','Explore the work through the questions it addresses: how to sense with light, and how to design the systems that make that possible.',[
        s('focus','A company presented through its work.','Artifactory is the company behind the two projects presented here. The proposed positioning connects sensing technology with tools for designing photonic systems. It gives investors and potential collaborators a way to assess the work at a company level.','The site concentrates on ArtiSense and AIFIELD. Their pages describe different purposes, stages and evidence boundaries rather than a single combined product.'),
        s('relationship','Related work, distinct responsibilities.','ArtiSense pursues a miniaturized chemical-sensing concept using photonics and signal interpretation. AIFIELD addresses photonic design and simulation, alongside a separate neural field research direction.','The internal glucose-related design example links an intended sensing objective to an engineering workflow. That connection does not make a simulated design a validated sensor, and the two projects’ neural subjects are not the same technology.',links=['projects']),
        s('known','Read the date with the claim.','The supplied context describes optical feasibility and chip-design work for ArtiSense. AIFIELD capability descriptions refer to a September 2026 snapshot. These provide a basis for a technical conversation while leaving current availability and further validation to be confirmed.','The approach page explains how concept, simulation and physical evidence should be distinguished. Project evidence pages keep the limits attached to the work they describe.',links=['approach']),
        s('conversation','Choose the conversation that fits.','Investors can begin with the company proposition and its unresolved development questions. Potential collaborators can start from a measurement, design or evaluation topic. A non-confidential introduction is enough for the first enquiry.','Use the contact page to describe your interest and preferred context. It provides an editable enquiry form and a public email route.',links=['investors','partnerships','contact'])],['investors','approach','partnerships','contact'])
    write('about','pl','Artifactory. Pomiary i inżynieria fotoniczna.','Poznaj obszar działania firmy łączący badania pomiarowe ArtiSense i narzędzia projektowe AIFIELD oraz ścieżki oceny dowodów i współpracy.','Poznaj prace przez pytania, na które odpowiadają: jak mierzyć za pomocą światła i jak projektować systemy, które to umożliwiają.',[
        s('focus','Firma przedstawiona przez swoje prace.','Artifactory jest firmą stojącą za dwoma prezentowanymi tu projektami. Proponowane pozycjonowanie łączy technologię pomiarową z narzędziami do projektowania systemów fotonicznych. Pozwala inwestorom i potencjalnym współpracownikom ocenić prace na poziomie firmy.','Strona koncentruje się na ArtiSense i AIFIELD. Ich opisy przedstawiają różne cele, etapy i granice dowodów, a nie jeden połączony produkt.'),
        s('relationship','Powiązane prace, odrębne odpowiedzialności.','ArtiSense rozwija koncepcję zminiaturyzowanego pomiaru składu chemicznego z wykorzystaniem fotoniki i interpretacji sygnałów. AIFIELD dotyczy projektowania i symulacji fotoniki oraz odrębnego kierunku badań neuronowych modeli pola.','Wewnętrzny przykład związany z glukozą łączy zamierzony cel pomiarowy z procesem inżynierskim. Powiązanie nie zmienia symulowanego projektu w zwalidowany czujnik, a neuronowe elementy obu projektów nie są tą samą technologią.',links=['projects']),
        s('known','Czytaj twierdzenie razem z datą.','Dostarczony kontekst opisuje prace nad wykonalnością optyczną i projektem chipu ArtiSense. Opisy możliwości AIFIELD odnoszą się do stanu z września 2026. Stanowią podstawę rozmowy technicznej, a bieżąca dostępność i dalsza walidacja wymagają potwierdzenia.','Strona o podejściu wyjaśnia rozróżnienie koncepcji, symulacji i dowodów fizycznych. Strony walidacji zachowują ograniczenia przy opisywanych pracach.',links=['approach']),
        s('conversation','Wybierz odpowiednią rozmowę.','Inwestorzy mogą zacząć od propozycji firmy i otwartych pytań rozwojowych. Potencjalni współpracownicy mogą wyjść od tematu pomiaru, projektowania lub oceny. Do pierwszego zapytania wystarczy niepoufne wprowadzenie.','Na stronie kontaktowej opisz zainteresowanie i preferowany kontekst. Dostępny jest edytowalny formularz oraz publiczny adres e-mail.',links=['investors','partnerships','contact'])],['investors','approach','partnerships','contact'])

def partnerships():
    write('partnerships','en','Bring a question we can investigate.','Proposed Artifactory collaboration topics in sensing, optical measurement, fabrication and testing, and photonic engineering-tool evaluation.','Useful collaboration starts with a specific technical question and the expertise needed to answer it.',[
        s('sensing','Sensing and optical measurement.','Possible ArtiSense discussions concern the optical response being sought, a suitable reference comparison and the effects that could obscure the signal. Expertise in controlled measurements, calibration and repeatability could help define what a meaningful experiment would need.','Describe the application context and which observation you could help evaluate. Non-invasive and wearable ambitions remain research directions; no clinical pilot or validated measurement capability is implied.',links=['artisense-technology','artisense-validation']),
        s('fabrication','Connect a design with a testable structure.','Potential fabrication and testing topics include process assumptions, tolerances, material behavior and the conditions needed to compare a physical structure with a model. The first task is to identify where the design assumptions may fail in implementation.','These are proposed discussion areas. The supplied material does not establish a manufacturing agreement, committed test program or existing partner relationship.'),
        s('tools','Evaluate the engineering workflow.','For AIFIELD, a useful evaluation begins with a bounded design task: its inputs, expected output and a reference method. Photonic designers can help assess how a workflow supports setup, comparison and result inspection.','Feedback on command-line or agent-assisted work should include human review responsibilities and the local/external data boundary. A demo request is a discussion about access and scope, not immediate product access.',links=['aifield-design','aifield-validation']),
        s('context','Give the first conversation enough context.','State the question, the expertise or facilities you can contribute and the evidence you would need to assess progress. Identify any constraints on sharing before sending design files or unpublished data. A short non-confidential description is sufficient.','The topics on this page are invitations to explore fit. They are not evidence of named partners, customers, letters of intent or committed pilots. Any relationship and permission to describe it publicly would need separate confirmation.',links=['contact'])],['artisense-technology','aifield-design','contact'])
    write('partnerships','pl','Zaproponuj pytanie do zbadania.','Proponowane tematy współpracy Artifactory: pomiary optyczne, wytwarzanie i testowanie oraz ocena narzędzi inżynierii fotonicznej.','Użyteczna współpraca zaczyna się od konkretnego pytania technicznego i wiedzy potrzebnej do udzielenia odpowiedzi.',[
        s('sensing','Pomiary i odpowiedź optyczna.','Możliwe rozmowy o ArtiSense dotyczą poszukiwanej odpowiedzi optycznej, właściwego porównania odniesienia i wpływów mogących przesłonić sygnał. Wiedza o kontrolowanych pomiarach, kalibracji i powtarzalności może pomóc określić wymagania wartościowego eksperymentu.','Opisz kontekst zastosowania i obserwację, którą możesz pomóc ocenić. Ambicje nieinwazyjne i ubieralne pozostają kierunkami badań; nie oznaczają pilotażu klinicznego ani zwalidowanej zdolności pomiarowej.',links=['artisense-technology','artisense-validation']),
        s('fabrication','Połącz projekt ze strukturą do zbadania.','Potencjalne tematy wytwarzania i testowania obejmują założenia procesu, tolerancje, zachowanie materiałów i warunki porównania struktury fizycznej z modelem. Pierwszym zadaniem jest wskazanie miejsc, w których założenia projektu mogą zawieść przy realizacji.','Są to proponowane obszary rozmowy. Dostarczony materiał nie potwierdza umowy produkcyjnej, uzgodnionego programu testów ani istniejącej relacji partnerskiej.'),
        s('tools','Oceń proces inżynierski.','W przypadku AIFIELD użyteczna ocena zaczyna się od ograniczonego zadania projektowego: danych, oczekiwanego wyniku i metody odniesienia. Projektanci fotoniki mogą pomóc ocenić wsparcie przygotowania, porównania i analizy rezultatów.','Informacja zwrotna o pracy przez wiersz poleceń lub z agentem powinna obejmować odpowiedzialność człowieka i granice przetwarzania lokalnego oraz zewnętrznego. Prośba o demo rozpoczyna rozmowę o dostępie i zakresie, nie daje natychmiastowego dostępu do produktu.',links=['aifield-design','aifield-validation']),
        s('context','Nadaj pierwszej rozmowie potrzebny kontekst.','Wskaż pytanie, wiedzę lub zaplecze, które możesz wnieść, oraz dowody potrzebne do oceny postępu. Określ ograniczenia udostępniania przed przesłaniem plików projektowych lub nieopublikowanych danych. Wystarczy krótki niepoufny opis.','Tematy na stronie zapraszają do oceny możliwości współpracy. Nie stanowią dowodu istnienia partnerów, klientów, listów intencyjnych ani uzgodnionych pilotaży. Każda relacja i zgoda na jej publiczny opis wymagają osobnego potwierdzenia.',links=['contact'])],['artisense-technology','aifield-design','contact'])

{'investors':investors,'approach':approach,'about':about,'partnerships':partnerships}[sys.argv[1]]()
